// Auswertung pro Video. Schema siehe sales_learning/README.md.
// seg = Segment: Handwerk · KMU · Großunternehmen · Privat · allgemein
// p = Phase: K = Kaltakquise · T = Termin/Verkaufsgespräch · A = andere Verkaufsform
// y = Typ: siehe README „Was aus den Videos herausgezogen wird“
// s = sinngemäß (schlechte Untertitel) · t = Zeitstempel
window.NOTES = {
"aaWn8bLoCQg": {"target":"Industrie (Produktionsleiter), Software","watch":true,"why":"Bestes Beispiel: kompletter Ablauf Sekretärin → Opener → Bedarfsfrage → Termin, guter Ton","items":[
  {"p":"K","y":"Sekretärin","t":"1:30","x":"„Wenn Sie mich gleich einmal weiterstellen, dann richten Sie gerne aus, der Julian Mahnken ist dran. Ich bleibe so lange in der Leitung.“"},
  {"p":"K","y":"Opener","t":"2:13","x":"„Jetzt können Sie mit meinem Namen vermutlich erst mal nichts anfangen, oder?“ … „Darf ich gleich mal sagen, warum ich anrufe?“"},
  {"p":"K","y":"Opener","t":"2:13","x":"„Wir möchten den Kontakt, der bisher eher virtuell stattgefunden hat, gerne mal persönlich machen. Es macht aber nur Sinn, wenn wir ein gemeinsames Thema haben, und deshalb habe ich eine kurze Frage. Ist das okay?“"},
  {"p":"K","y":"Bedarfsfrage","t":"3:00","x":"„Mal angenommen, Sie würden sich mit [X] befassen, die Sie sofort warnt, wenn … – was müsste so eine Lösung können, damit das für Sie interessant wird?“"},
  {"p":"K","y":"Einwand","e":"Haben wir schon","t":"3:00","x":"„Sie haben so eine Software bereits im Einsatz – super, perfekt. Vor dem Hintergrund, dass nichts auf dieser Welt perfekt ist: Wenn Sie über den Alltag nachdenken, was man noch besser machen könnte oder was fehlt – was fällt Ihnen spontan ein?“"},
  {"p":"K","y":"Einwand","e":"Haben wir schon","t":"4:00","x":"Lücke prüfen: „Ist dieses System auch in der Lage, Ihnen Ausfälle anzuzeigen, bevor etwas passiert?“ → „Was würde es für Sie bedeuten, wenn wir das bestehende System nicht ersetzen, sondern um diese Funktion ergänzen?“"},
  {"p":"K","y":"Terminvereinbarung","t":"5:02","x":"„Mein Vorschlag wäre, dass wir erst mal eine Web-Präsentation machen … da nehmen wir uns ganz entspannt beim Kaffee 20 Minuten. Wie klingt das für Sie?“"},
  {"p":"K","y":"Einwand","e":"Rufen Sie später wieder an","t":"6:00","x":"„Können wir gerne so machen. Ich würde Ihnen sonst aber, weil mein Kalender sehr schnell für zwei Wochen ausgeplant ist und wir es sonst ewig vor uns herschieben, gleich zwei, drei Terminvorschläge per E-Mail schicken. Dann können wir den schon mal reservieren. Wollen wir das so machen?“"},
  {"p":"K","y":"Prinzip","t":"7:03","x":"Bei „haben wir schon“ nicht argumentieren, sondern nachfragen, was darüber hinaus interessant wäre."}],"seg":"KMU"},
"tluPk9kCpkU": {"target":"","watch":false,"why":"","items":[
  ],"skip":"Doppelt: dasselbe Gespräch wie aaWn8bLoCQg","seg":"allgemein"},
"F_RgIbBdiyE": {"target":"Marketingagenturen (Dienstleistung Telefonakquise)","watch":true,"why":"Einwand „keine Zeit“ charmant gedreht, 4 min","items":[
  {"p":"K","y":"Opener","t":"1:00","x":"„Ich bin Profi in Sachen Telefonakquise. Das bedeutet, ich vereinbare für Marketingagenturen qualifizierte Termine auf Entscheiderebene. Jetzt habe ich mir gedacht, dass es vertrieblich bei Ihnen wahrscheinlich schon gut läuft. Die Frage war: Wenn man das Gute noch mal besser machen kann, ist das grundsätzlich interessant, dass wir uns die kommenden Tage mal austauschen?“"},
  {"p":"K","y":"Einwand","e":"Keine Zeit / gleich Meeting","t":"1:00","x":"„Ich hör's raus. Wann passt es besser?“ → Uhrzeit festmachen"},
  {"p":"K","y":"Bedarfsfrage","t":"2:01","x":"„Eine letzte Frage noch gestattet, ganz schnell: Was wäre das Wichtigste, das wir als Dienstleister einbringen müssten, damit es für Sie interessant ist?“"}],"seg":"KMU"},
"wLrZYtekimY": {"target":"KMU / Online-Marketing","watch":true,"why":"Zwei Gespräche: falscher Geschäftsführer gibt Durchwahl des richtigen","items":[
  {"p":"K","y":"Prinzip","t":"9:01","x":"Immer ganz oben anrufen (Geschäftsführer laut Impressum); bei falscher Person Durchwahl der richtigen geben lassen."},
  {"p":"K","y":"Opener","t":"5:01","s":1,"x":"Zweiter Anruf: „Ich hatte gerade ein Gespräch mit [Name], er hat mir direkt Ihre Nummer gegeben, weil er sagte, das ist eher Ihr Thema.“"},
  {"p":"K","y":"Bedarfsfrage","t":"6:02","s":1,"x":"„Was müsste Inhalt und Ergebnis eines Gesprächs mit uns sein, welche Ergebnisse müssten wir Ihnen sichern können, damit es für Sie interessant ist?“"},
  {"p":"K","y":"Terminvereinbarung","t":"7:03","s":1,"x":"„Sie kennen uns ja nicht, und am Telefon kann ich viel versprechen. Ich würde Ihnen gerne einmal ganz transparent aufzeigen, welche bewährten Methoden wir nutzen … 20 bis 30 Minuten.“"}],"seg":"KMU"},
"H4jjJFVrCaY": {"target":"KMU / Online-Marketing","watch":false,"why":"","items":[
  {"p":"K","y":"Opener","t":"0:01","s":1,"x":"„Ich kann mir gut vorstellen, wenn ich Ihnen sage, dass ich beruflich in Sachen Online-Marketing unterwegs bin, dass Sie erst mal denken: nicht schon wieder einer von der Sorte – oder liege ich da vollkommen falsch?“"},
  {"p":"K","y":"Bedarfsfrage","t":"0:01","s":1,"x":"„Was müsste jemand eigentlich können und nachweislich im Ergebnis liefern, damit es für Sie überhaupt interessant wird?“"},
  {"p":"K","y":"Leitfaden","t":"1:02","s":1,"x":"Angebot erklären in zwei Zielen: 1. Leute, die aktiv suchen, auf die Website holen; 2. Website so gestalten, dass aus anonymen Besuchern Anfragen werden."},
  {"p":"K","y":"Terminvereinbarung","t":"2:00","s":1,"x":"„Es ist kein Zufall, dass ich Sie angerufen habe – ich betreue schon viele Kunden in einem ähnlichen Bereich … ich würde Ihnen gerne vorschlagen, dass wir zusammen eine Web-Session machen, eine halbe Stunde, und ich zeige Ihnen transparent, was wir bisher leisten, damit Sie selbst beurteilen können.“"}],"seg":"KMU"},
"FCeUPxi_Nvg": {"target":"Unternehmen mit Vertrieb (Dienstleistung Telefonakquise)","watch":false,"why":"","items":[
  {"p":"K","y":"Opener","t":"0:03","s":1,"x":"„Ich mache es ganz offen: Ich bin Profi in Sachen Telefonakquise … ich gehe davon aus, dass es bei Ihnen vertrieblich gut läuft. Die Frage war: Wenn man das Gute noch mal besser machen kann, sind Sie da grundsätzlich offen?“"},
  {"p":"K","y":"Einwand","e":"Was kostet das? / Fixum","t":"1:02","s":1,"x":"„Wir bekommen kein Fixum wie bei vielen Agenturen, sondern werden provisionsbasiert pro Termin bezahlt, und nur, wenn er stattfindet.“"},
  {"p":"K","y":"Organisation","t":"5:00","x":"Bezahlung pro stattgefundenem Termin, nicht pro Auftrag – nur das, was man selbst zu 100 % beeinflusst."}],"seg":"KMU"},
"anRkPyRjsp8": {"target":"Mittelstand / Werbeagentur","watch":false,"why":"","items":[
  {"p":"K","y":"Bedarfsfrage","t":"1:01","s":1,"x":"„Wenn Sie auf einen externen Dienstleister zurückgreifen würden und prüfen würden, ob wir geeignet sind – worauf würden Sie Wert legen, unter welchen Voraussetzungen wäre das überhaupt was?“"},
  {"p":"K","y":"Einwand","e":"Kein Bedarf / brauchen kein Marketing","t":"3:09","s":1,"x":"„Ich bin großer Fan davon, dass wir mit unserer Zeit gegenseitig respektvoll umgehen und nichts machen, was keinen Sinn macht – aber den Kontakt sinnvoll weiterführen. Ich würde mich gerne kurz mit Ihnen austauschen, damit Sie eine Bewertungsgrundlage haben, wenn es zu gegebener Zeit so weit ist.“"}],"seg":"KMU"},
"u332FoQeK_M": {"target":"Gebäudereinigung","watch":false,"why":"","items":[
  {"p":"K","y":"Einwand","e":"Haben schon einen Dienstleister / Vertrag","t":"2:23","s":1,"x":"Kontakt halten statt drängen: „Dass wir uns einfach mal persönlich kennenlernen, 20 Minuten, und Sie uns schon mal in der Schublade haben, wenn es so weit ist.“"}],"seg":"KMU"},
"00xJqgLwkFg": {"target":"Personalberatung / Headhunter (Lackindustrie)","watch":false,"why":"","items":[
  {"p":"K","y":"Nachfassen","t":"1:01","s":1,"x":"Reaktivierung: „Ich bin neu hier und habe gesehen, unsere Firmen standen vor einiger Zeit in Kontakt. Vielleicht kann man das wieder intensivieren – aber natürlich nur, wenn es Sinn macht.“"},
  {"p":"K","y":"Nachfassen","t":"1:01","s":1,"x":"„Unter welchen Voraussetzungen wäre es für Sie prinzipiell interessant und vor allem sinnvoll, dass wir den Kontakt in der Zukunft wieder aufnehmen?“"}],"seg":"KMU"},
"DQJ0l_idr50": {"target":"Immobilienmakler → Privatverkäufer","watch":false,"why":"","items":[
  {"p":"K","y":"Bedarfsfrage","t":"1:01","s":1,"x":"„Angenommen, es käme ein Käufer über einen Makler, der zu Ihren Bedingungen und Ihrem Preis kauft – wäre es dann ein Ausschlusskriterium, dass ein Makler dabei ist?“"},
  {"p":"K","y":"Prinzip","t":"3:02","s":1,"x":"Ehrlich bleiben: „Wir kennen uns jetzt zwei Minuten, ich sage es ganz offen: Ich habe in diesem Moment noch keinen Käufer.“"}],"seg":"Privat"},
"zdFAzni-M1s": {"target":"B2B allgemein","watch":true,"why":"4 Sekretärinnen live hintereinander, 3× sofort durchgestellt – Ton und Selbstverständlichkeit hören","items":[
  {"p":"K","y":"Sekretärin","t":"1:01","x":"„Wenn Sie mich gleich einmal zum [Vorname Nachname] weiterstellen, dann richten Sie gerne aus, der [Name] ist dran. Ich bleibe so lange in der Leitung.“"},
  {"p":"K","y":"Prinzip","t":"6:03","x":"Zielperson mit Vor- und Nachnamen nennen, als Bitte statt Frage; Selbstverständlichkeit in der Stimme verhindert „Worum geht es?“."},
  {"p":"K","y":"Sekretärin","t":"5:03","x":"Wenn nicht im Haus: nicht pitchen, nur fragen, wann er wieder da ist, und später erneut anrufen."}],"seg":"allgemein"},
"vePdGc0hxew": {"target":"B2B / IT (IT-Leiter)","watch":true,"why":"Ab 36:00 wird ein kompletter Kaltakquise-Leitfaden (Tim Taxis) im Fließtext durchgespielt – Sekretärin bis Termin","items":[
  {"p":"K","y":"Sekretärin","t":"5:00","x":"„[Name der Sekretärin], guten Morgen, Frau [Name], mein Name ist [Vorname Nachname] von der Firma [X].“ – dann PAUSE und den Gruß erwidern lassen. Kein Wortschwall: Dialog statt Verkaufsgespräch. ⚠️ Überholt: In pacRsnbOZ2o (neuer) rät Julian ab, die Sekretärin mit Namen anzusprechen und den Firmennamen zu nennen."},
  {"p":"K","y":"Sekretärin","t":"6:01","x":"„Sagen Sie, Frau [Name], ist der Herr [Nachname] heute schon im Haus?“ – „Ja.“ – „Dann verbinden Sie mich bitte mit ihm, danke schön.“ Julian: Zielperson mit „Herr Nachname“ oder vollem Namen nennen, nicht „der Werner Richter“."},
  {"p":"K","y":"Sekretärin","t":"12:00","x":"Variante (Kreuter) auf „Worum geht es?“: „Um seine IT-Infrastruktur, speziell die Verbesserung seiner Systemerreichbarkeit. Dazu brauche ich seine Entscheidung als IT-Chef. Bitte verbinden Sie mich mit ihm, danke schön.“ – Julian: Schulnote 3."},
  {"p":"K","y":"Prinzip","t":"15:01","x":"Bei der Sekretärin inhaltlich nicht preisgeben, worum es geht – sobald „Verkäufer“ erkennbar ist, kommt „Schicken Sie eine Mail an info@“. Nicht lange erklären, kurz und mit abschließender Bitte."},
  {"p":"K","y":"Prinzip","t":"14:01","x":"Bei der Sekretärin keine Vorteile nennen und nicht schmeicheln – künstliche Sympathie wirkt unecht."},
  {"p":"K","y":"Opener","t":"18:01","x":"Nicht: „Hätten Sie zehn Minuten Zeit für mich?“ oder „Kennen Sie uns schon?“ – wirkt wie Betteln."},
  {"p":"K","y":"Opener","t":"22:00","x":"„Herr [Nachname], darf ich gleich zum Punkt kommen?“ – Julian empfiehlt es: holt Erlaubnis ein, statt ungefragt loszureden. Wegen Bekanntheit lieber eigene Variante: „Darf ich gleich mal sagen, warum ich anrufe?“ (44:00)"},
  {"p":"K","y":"Opener","t":"23:01","x":"„Wir möchten Ihr zusätzlicher strategischer [IT-]Partner werden – aber nur, wenn das für Sie auch wirklich Sinn macht. Dazu habe ich eine kurze Frage. Ist das okay für Sie?“ – Julian: „super“, nennt das Thema, argumentiert nicht, endet mit Frage."},
  {"p":"K","y":"Prinzip","t":"26:00","x":"„Wer fragt, der führt“: Jede eigene Aussage mit einer Frage abschließen und den Gesprächspartner so Schritt für Schritt Richtung Termin führen."},
  {"p":"K","y":"Prinzip","t":"27:02","x":"Keine zwei Argumente/Vorteile im Opener (alte Schule): Argumente erzeugen Druck → Totstellen, Flucht oder Gegenangriff. Und du weißt beim Kaltanruf nicht, welches Argument für ihn zählt – erst Bedarf ermitteln."},
  {"p":"K","y":"Bedarfsfrage","t":"31:01","x":"„Wenn es eine Sache im Bereich Ihrer [IT-Infrastruktur] gibt, die nicht immer so läuft, wie Sie sich das als [IT-Leiter] wünschen – welche eine Sache ist das?“ – Julian: gut, aber oft kommt „läuft alles gut“."},
  {"p":"K","y":"Bedarfsfrage","t":"36:00","x":"Vertiefen: „Wie müsste denn [die Erreichbarkeit im Bereich der Handelssysteme] bei Ihnen aussehen, damit es optimal passt?“"},
  {"p":"K","y":"Terminvereinbarung","t":"37:00","x":"„Wunderbar, dann macht ein gemeinsames Gespräch auf alle Fälle Sinn. Wie Sie [die gesteigerte Erreichbarkeit auf Klasse 4] lösen, sehen Sie nächste Woche. Wann passt es denn bei Ihnen optimal?“ – dann zwei konkrete Terminvorschläge."},
  {"p":"K","y":"Leitfaden","t":"36:00","x":"Gesamtablauf (Tim Taxis): Begrüßung + Name → „Darf ich gleich zum Punkt kommen?“ → Thema + „aber nur, wenn es Sinn macht – kurze Frage, okay?“ → „Welche eine Sache läuft nicht so, wie Sie es wünschen?“ → „Wie müsste es aussehen, damit es optimal passt?“ → „Dann macht ein Gespräch Sinn – wann passt es optimal?“"},
  {"p":"K","y":"Prinzip","t":"41:02","x":"Sie-Formulierung („Sie sehen nächste Woche …“ statt „Ich zeige Ihnen …“) – Julian hält sie für überbewertet; wichtiger sei, dass die Worte authentisch zu dir passen."}],"seg":"KMU"},
"EsK12QRwpU4": {"target":"Aktien-Telefonverkauf an Privatanleger (Filmszene)","watch":false,"why":"","items":[
  {"p":"A","y":"Opener","t":"1:01","x":"Bedarf wecken über Problembewusstsein: „Der Trick ist, sich vorher zu positionieren – wenn es im Wall Street Journal steht, ist es zu spät.“ → Kunde erkennt, warum er zuhören sollte."},
  {"p":"A","y":"Prinzip","t":"3:01","x":"Nach einer wichtigen Frage, vor allem der Abschlussfrage: schweigen und warten („Wer zuerst spricht, verliert“). Viele verquatschen den Abschluss."},
  {"p":"A","y":"Prinzip","t":"4:01","x":"„Ihr einziger wirklicher Einwand ist, dass Sie mir nicht vertrauen.“ – Die meisten Einwände („Schicken Sie Unterlagen“, „Ich muss drüber schlafen“) sind Vorwände wegen fehlendem Vertrauen."},
  {"p":"A","y":"Einwand","e":"Ich kenne Sie nicht / kein Vertrauen","t":"7:00","x":"Vertrauen aufbauen über Expertenstatus (Position nennen) + kurze Story, warum man sich keine Fehler leisten kann: „Ich will der Beste hier werden – das schaffe ich nicht, wenn ich mir Fehler erlaube.“"},
  {"p":"A","y":"Leitfaden","t":"6:02","x":"Future Pacing: Kunden gedanklich in die Wunschsituation holen – „Wenn das so eingetreten ist, würden Sie dann nicht sagen, dass es sich gelohnt hat?“"},
  {"p":"A","y":"Leitfaden","t":"9:01","x":"Kontrollfrage nach dem Nutzen: „Klingt das fair?“"}],"seg":"Privat"},
"vKmkzP0565I": {"target":"Verkäufer selbst (Telefonangst)","watch":false,"why":"","items":[
  {"p":"K","y":"Organisation","t":"7:00","x":"Vor dem ersten Anruf: Nummer vorwählen, Handy hinlegen, Augen zu, 4 Sek. durch die Nase in den Bauch einatmen, 8 Sek. durch den Mund ausatmen, 60–90 Sek. lang. Dann ohne Nachdenken auf den grünen Hörer drücken."},
  {"p":"K","y":"Organisation","t":"9:01","x":"Nur der erste Anruf braucht Überwindung („Sprung ins kalte Wasser“) – danach direkt die nächsten Nummern wählen."}],"seg":"allgemein"},
"Q31kjBQP4VA": {"target":"B2B allgemein","watch":false,"why":"","items":[
  {"p":"K","y":"Prinzip","t":"0:00","x":"Nach der Begrüßung nicht ungefragt losreden („Fußgängerzone“) – erst Erlaubnis holen, sonst kommen sofort Einwände."},
  {"p":"K","y":"Prinzip","t":"2:01","x":"Nicht argumentieren: Argumente erzeugen Druck und Gegendruck („Talkshow“). Stattdessen fragen."}],"seg":"allgemein"},
"639wCGS1SA4": {"target":"B2B allgemein (interne Schulung für Telefonakquise-Mitarbeiter)","watch":true,"why":"Kern seiner Einwandbehandlung: Reframing-Formel erklärt und mit Mitarbeiter geübt – die Formulierungs-Feinheiten hört man am besten selbst","items":[
  {"p":"K","y":"Leitfaden","t":"1:00","x":"Nach dem Interesse-Wecken gibt es nur drei Reaktionen: 1. klares Interesse → direkt Terminvereinbarung („Dann lassen Sie uns mal schauen, wann es die Tage passt“); 2. Einwand → Einwandbehandlung; 3. Rückfrage → kurz antworten, dann zur Terminvereinbarung."},
  {"p":"K","y":"Prinzip","t":"2:01","x":"Rückfragen („Was kostet das?“, „Wie macht ihr das genau?“) sind Kaufsignale. Kurz und knapp beantworten, nie die Verkaufspräsentation vorwegnehmen, sofort zum Termin überleiten."},
  {"p":"K","y":"Prinzip","t":"3:00","x":"In der Kaltakquise nicht argumentieren („Wir sind günstiger/besser als alle anderen“): Es fehlt das Vertrauen, Argumente verpuffen und drängen den Kunden in die Ecke."},
  {"p":"K","y":"Prinzip","t":"5:00","x":"Negativbeispiel: „Sie wissen ja gar nicht, woran Sie kein Interesse haben, Sie kennen mein Angebot noch gar nicht.“ – logisch richtig, aber der Kunde muss sich rechtfertigen."},
  {"p":"K","y":"Leitfaden","t":"6:01","x":"Reframing-Formel: Einwand = Problem des Kunden → Lösung als Bedingung zurückgeben: „Okay, das heißt nur, wenn [Lösung], nur dann macht es Sinn, dass wir sprechen – andernfalls nicht, oder?“"},
  {"p":"K","y":"Einwand","e":"Schlechte Erfahrungen gemacht","t":"6:01","x":"„Okay, das heißt nur, wenn wir sicherstellen, dass sich die schlechte Erfahrung nicht wiederholt – nur dann macht es Sinn, dass wir sprechen. Andernfalls nicht, oder?“"},
  {"p":"K","y":"Einwand","e":"Haben schon einen Partner","t":"7:03","x":"„Okay, das heißt nur, wenn ich Ihnen ein viel besseres Angebot mache als Ihr aktueller Partner – dann hätte sich ein Vergleich für Sie gelohnt. Könnte man das so sagen?“"},
  {"p":"K","y":"Einwand","e":"Keine Zeit / viel zu tun","t":"7:03","x":"„Okay, das heißt nur, wenn wir noch eine kleine Lücke in Ihrem Kalender finden und es ganz kurz halten, also nicht viel mehr von Ihrer Zeit in Anspruch nehmen – nur dann macht es Sinn, dass wir in den Kalender schauen.“"},
  {"p":"K","y":"Einwand","e":"Ich glaube Ihnen das nicht","t":"11:00","x":"„Das heißt nur, wenn ich es nicht nur behaupte, sondern auch beweisen kann – nur dann macht unser Gespräch Sinn. Stimmt's?“"},
  {"p":"K","y":"Einwand","e":"Sie sind schon der Zehnte, der anruft","t":"12:02","x":"„Das heißt nur, wenn wir endlich mal die Ersten sind, die auch wirklich etwas Interessantes anzubieten haben – dann macht es Sinn, dass wir das Gespräch fortführen, oder?“"},
  {"p":"K","y":"Prinzip","t":"8:00","x":"Immer das Kundeninteresse in den Mittelpunkt stellen statt „Ich würde Ihnen gerne zeigen …“ – Sätze so umformulieren, dass der Kunde merkt: Es geht um mich."},
  {"p":"K","y":"Prinzip","t":"13:01","x":"Rapport als „Vertrauenskonto“: Jeder Widerstand hebt viel ab. Alles im Gespräch soll einzahlen, deshalb Widerstand vermeiden."}],"seg":"allgemein"},
"pW3HJaqKwoM": {"target":"B2B allgemein","watch":false,"why":"","items":[
  {"p":"K","y":"Opener","t":"2:02","s":1,"x":"Begrüßung: „Hallo Herr [Nachname], hier ist [Vorname Nachname], grüß Sie.“ – Name des Gesprächspartners zuerst (holt ihn wie ein Zuruf in der Fußgängerzone aus seinen Gedanken), „hier ist“ statt „mein Name ist“ (klingt vertraut), Vor- und Nachname ohne Titel."},
  {"p":"K","y":"Prinzip","t":"6:01","x":"Firmennamen in der Begrüßung weglassen, außer die Firma ist weltbekannt – eine weitere fremde Information, die sich niemand merkt und die keinen Vorteil bringt."},
  {"p":"K","y":"Prinzip","t":"8:01","x":"Das „grüß Sie“ am Satzende ist Antwortauslöser: Der Gesprächspartner erwidert den Gruß → von Anfang an Dialog statt Monolog."},
  {"p":"K","y":"Opener","t":"15:00","x":"„Herr [Nachname], darf ich gleich mal sagen, warum ich anrufe?“ – wie vePdGc0hxew: Julians eigene Variante von Tim Taxis' „Darf ich gleich zum Punkt kommen?“; Ziel ist die aktive Zustimmung zum Gespräch statt ungefragt loszureden."},
  {"p":"K","y":"Leitfaden","t":"10:00","x":"Begrüßung und Gesprächseinstieg sind Schritt 1 und 2 von fünf; die Schritte 3–5 erklärt das Video nicht."}],"seg":"allgemein"},
"t1y4G4gELSw": {"target":"B2B (Julians eigene Akquise, Vlog)","watch":false,"why":"","items":[
  {"p":"K","y":"Organisation","t":"21:01","x":"Ergebnis seiner 100-Calls-Challenge (13–17 Uhr): 77 Wählversuche → 12 Entscheidergespräche → 9 Termine. Ab ca. 40 Calls lassen Konzentration und Schlagfertigkeit in der Einwandbehandlung nach. Julian: lieber ca. 20 Wählversuche am Tag, Qualität vor Quantität."},
  {"p":"K","y":"Organisation","t":"15:02","x":"Einen Termin aus einem eigentlichen Nein herausgeholt – Julian: solche Termine sind meist schlecht qualifiziert, „da macht es häufig gar keinen Sinn, die wahrzunehmen“."},
  {"p":"K","y":"Organisation","t":"7:03","x":"Beim Energieloch kurze Pause (Bewegung, frische Luft, Kaffee) statt weiterzuwählen – die Stimme transportiert die Energie."},
  {"p":"K","y":"Organisation","t":"6:00","x":"Während des Telefonblocks nur Strichliste und Zettel (Termin, E-Mail für die Bestätigung); Bestätigungsmails abends verschicken – keine Zeit zwischen den Anrufen verlieren."},
  {"p":"K","y":"Organisation","t":"12:01","x":"Adressrecherche kostenlos über wlw.de („Wer liefert was“): Suchbegriff, dann nach Mitarbeiterzahl (z. B. 10–49) und Standort mit Umkreis filtern – statt Adressen zu kaufen."}],"seg":"allgemein"},
"pmVzqS9YJpE": {"target":"Industrie (Produktionsleiter), Software","watch":false,"why":"","items":[
  {"p":"K","y":"Organisation","t":"1:00","x":"Reaktionsvideo auf das Gespräch aus aaWn8bLoCQg – Formulierungen dort; hier nur Julians neue Erklärungen."},
  {"p":"K","y":"Opener","t":"5:14","s":1,"x":"Aufhänger: „Vielleicht erinnern Sie sich ganz dunkel daran, dass Sie mal ein Whitepaper zum Thema Industrie 4.0 von uns runtergeladen haben.“ – Julian gibt zu: Dieses Whitepaper gab es nicht. ⚠️ Erfundener Anknüpfungspunkt, nicht übernehmen; laut Julian ist ein Aufhänger „gar nicht notwendig“."},
  {"p":"K","y":"Prinzip","t":"7:01","x":"Bedarfsfrage rückwärts bauen: zuerst überlegen, welche Antwort man vom Kunden hören möchte, dann die Frage so stellen, dass genau diese Antwort kommt (hier: Maschinenstillstand kostet Produktionsleiter viel Geld)."},
  {"p":"K","y":"Einwand","e":"Haben wir schon","t":"12:01","s":1,"x":"Genannte Schwäche bestätigen statt dagegen argumentieren: „Ich bin aber vollkommen bei Ihnen, wenn Sie sagen: Nur wegen des Handlings stellt man nicht gleich in einem großen Projekt alles um.“ → dann Lücke prüfen wie aaWn8bLoCQg. Julian: Das Alleinstellungsmerkmal erst bringen, wenn Vertrauen da ist."},
  {"p":"K","y":"Terminvereinbarung","t":"14:01","s":1,"x":"Den vom Kunden genannten Schmerz in den Terminvorschlag einbauen: „… und dann schauen Sie sich mal an, wie einfach vor allem das Handling ist.“ – Termingrund sind zwei Nutzen, die der Kunde selbst angesprochen hat."},
  {"p":"K","y":"Prinzip","t":"11:00","x":"Am Telefon bewusst lächeln – hört man in der Stimme."},
  {"p":"K","y":"Terminvereinbarung","t":"15:00","x":"Produktionsleiter haben den Kalender selten griffbereit → Terminvorschläge per Mail schicken und dort festmachen (Formulierung wie aaWn8bLoCQg 6:00)."}],"seg":"KMU"},
"LdSGGgKC5jA": {"target":"B2B allgemein","watch":true,"why":"Short (unter 1 Min.): Julians Antwort auf „Worum geht's denn?“ ist in den Untertiteln unverständlich – selbst anhören","items":[
  {"p":"K","y":"Sekretärin","t":"0:00","s":1,"x":"„Hallo, hier ist der [Vorname Nachname], grüß Sie. … Wenn Sie mich einmal weiterstellen zum [Vorname Nachname], dann richten Sie gerne aus, der [Name] ist dran. Ich bleibe so lange in der Leitung.“ – wie zdFAzni-M1s; die Antwort auf die Rückfrage ist nicht verständlich transkribiert."}],"seg":"allgemein"},
"_e9NAQuvtlk": {"target":"Verkäufer selbst (Motivation)","watch":false,"why":"","items":[
  {"p":"K","y":"Organisation","t":"2:01","x":"Wert eines Wählversuchs ausrechnen (Beispielrechnung: 100 Wählversuche → 10 Termine → 5 Aufträge à 1.000 € = 50 € pro gewählter Nummer). Mit den eigenen Quoten rechnen – jeder Anruf ist dann „50 € in die Tasche“."},
  {"p":"K","y":"Organisation","t":"4:01","x":"Schmerz vermeiden: Tagesziel (z. B. 50 Nummern) als Bargeld links auf den Schreibtisch, pro 5 gewählte Nummern 50 € nach rechts; was abends noch links liegt, wird verbrannt. Julian: radikal, nur für Druckresistente."}],"seg":"allgemein"},
"EJyUFrP_oOQ": {"seg":"Handwerk","target":"HANDWERK: Agenturen (Webdesign, Social Recruiting, KI) → Handwerksbetriebe","watch":false,"why":"","items":[
  {"p":"K","y":"Prinzip","t":"1:01","x":"Handwerk-Besonderheit: Betriebe werden seit Jahren mehrmals täglich von Agenturen angerufen (Webdesign, Social Recruiting, KI), alle klingen gleich → pauschal ablehnende Haltung, auch bei echtem Bedarf. Handwerker sind „sehr direkte Typen“ mit direkter Sprache; beim fünften Agenturanruf vor 12 Uhr verständlich genervt."},
  {"p":"K","y":"Prinzip","t":"4:01","x":"Lösung ist nicht Zielgruppe wechseln oder mehr wählen, sondern positiv aus der Masse herausstechen – mit demselben Thema, offen genannt, ohne falsche Erwartung zu wecken, aber eleganter formuliert und mit gezielt eingesetzter Stimme: „Da haben sich diese Woche schon 30 gemeldet, du bist der 31. Und du bist aber der erste, der einen Termin vereinbart, weil du der erste bist, der dann ein anderes Gefühl bei ihm auslöst.“"}]},
"KKvUr--VrQE": {"seg":"allgemein","target":"Eventagentur → Unternehmen mit Tochterfirma (Live-Mitschnitt); Handwerk nur am Rande (Webdesign-Teilnehmer)","watch":true,"why":"Live-Mitschnitt: Einwand „machen wir intern“ wird in Sekunden per Reframing gelöst und direkt in die Uhrzeit übergeleitet – Timing hören","items":[
  {"p":"K","y":"Bedarfsfrage","t":"2:01","x":"„Wenn Sie dafür bei uns, ich sag mal, das beste Preis-Leistungsverhältnis bekommen, spricht dann rein rational irgendwas dagegen, dass Sie unser Angebot zumindest mal prüfen?“"},
  {"p":"K","y":"Einwand","e":"Machen wir intern / eigene Tochterfirma","t":"2:01","s":1,"x":"Live: „Ich verstehe das, ich denke, das macht wahrscheinlich nur unter der Voraussetzung Sinn, wenn wir eine wirklich sinnvolle Ergänzung zu dem darstellen können, oder?“ – „Genau.“ – sofort: „Hätten Sie jetzt irgendwie 11 Uhr Zeit oder ein bisschen später?“"},
  {"p":"K","y":"Einwand","e":"Machen wir intern / eigene Tochterfirma","t":"3:02","x":"Saubere Fassung: „Das heißt nur, wenn wir zu dem, was die Tochterfirma da macht, eine wirklich sinnvolle Ergänzung darstellen können, nur dann macht Sinn, dass wir da mal drüber sprechen, stimmt's?“ – wiederkehrende Reframing-Formel wie 639wCGS1SA4."},
  {"p":"K","y":"Prinzip","t":"4:02","x":"Bei internem Team, Tochterfirma oder persönlicher Beziehung nicht „besseres Angebot als der Partner“ anbieten, sondern „sinnvolle Ergänzung“ – niemand will die eigenen Leute rauskegeln oder Ärger mit der Tochterfirma."},
  {"p":"K","y":"Prinzip","t":"7:00","x":"Gereizte Reaktionen („Sie haben 90 Sekunden“) sind meist Reaktion auf den eigenen Einstieg (Pitch-„Überfallkommando“). Einwandbehandlung funktioniert nur in lockerer Atmosphäre auf Augenhöhe – der Gesprächsaufbau davor entscheidet."}]},
"kAQN4KU455Q": {"seg":"KMU","target":"B2B mit mehreren Geschäftsführern (Beispiel: Verkaufstraining)","watch":false,"why":"","items":[
  {"p":"T","y":"Abschluss","t":"1:01","x":"Mehrere Entscheider: Nicht auf das Closing-Gespräch verzichten, wenn nicht alle kommen können. „Closing-Gespräch 1“ voll mit dem einen Entscheider führen – Abschluss dort zu 99 % nicht, aber Ziel ist, ihn so zu begeistern, dass er intern die anderen überzeugt."},
  {"p":"T","y":"Abschluss","t":"3:00","x":"Kein „Staatsgeheimnis“ aus dem Angebot machen („Erzähle ich erst, wenn alle am Tisch sitzen“) – dann hat der Entscheider intern keine Argumente, um Kollegen eine Stunde blocken zu lassen."},
  {"p":"T","y":"Abschluss","t":"7:00","x":"Am Ende von Closing 1: „Wie holen wir denn jetzt Ihre Kollegen ins Boot?“ → Closing 2 mit allen terminieren. Teils unterschreibt der begeisterte Entscheider auch ohne zweites Gespräch."},
  {"p":"K","y":"Prinzip","t":"9:01","x":"Nur mit echten Entscheidern sprechen („die Treppe von oben kehren“) – wie wLrZYtekimY. Beispiel: Im kleinen Unternehmen entscheidet nicht der Personalleiter, sondern der Geschäftsführer; Termine mit Nicht-Entscheidern sind „oftmals nur Beschäftigungstherapie“."},
  {"p":"K","y":"Nachfassen","e":"Follow-up nach Monaten","t":"11:01","x":"Nicht nur: „Wir haben ja vor drei Monaten gesprochen … wie sieht es denn bei Ihnen aktuell aus?“ (zündet nicht an). Stattdessen erneut in die Bedarfsermittlung: „Wir haben uns ja committed, heute nach drei Monaten noch mal zu sprechen. Wie ist der Stand der Dinge bei Ihnen?“ – dann gezielte Fragen, um den Bedarf größer zu machen."}]},
"uQhEkID92pI": {"seg":"allgemein","target":"B2B allgemein (Flipchart-Erklärung Reframing)","watch":false,"why":"","items":[
  {"p":"K","y":"Einwand","e":"Keine Zeit","t":"5:00","x":"„Okay, das heißt nur, wenn wir einen Zeitpunkt finden, der für Sie noch gut reinpasst und wo wir es dann kurz halten, dann macht Sinn, dass wir jetzt noch mal kurz in den Kalender schauen. Stimmt's?“ – Reframing wie 639wCGS1SA4."},
  {"p":"K","y":"Einwand","e":"Machen wir intern","t":"5:00","x":"„Okay, das heißt nur, wenn wir zu dem, was da intern schon gut funktioniert, eine wirklich sinnvolle Ergänzung darstellen können, nur dann macht Sinn, dass wir da noch mal drüber sprechen. Richtig?“"},
  {"p":"K","y":"Terminvereinbarung","t":"5:00","x":"Nach dem Ja auf das Reframing sofort überleiten, Lösung als Termingrund: „Okay, dann lassen Sie uns mal schauen, wann es die Tage passt, weil dann zeige ich Ihnen, wie wir das für Sie sicherstellen.“"},
  {"p":"K","y":"Terminvereinbarung","e":"Haben schon einen Partner","t":"6:01","x":"„Dann lassen Sie uns noch mal schauen, wann wir die Tage sprechen. Dann zeige ich Ihnen mal unser Angebot, wir legen mal nebeneinander, und Sie können dann entscheiden: Machen Sie mit dem aktuellen Partner weiter oder sind wir vielleicht eine ganz gute Option?“"},
  {"p":"K","y":"Einwand","e":"Ketteneinwand: machen intern, weil schlechte Erfahrung","t":"6:01","x":"Zweiter Einwand nach dem Reframing → noch einmal reframen: „Ah okay, das heißt nur, wenn wir zusätzlich sicherstellen, dass sich die schlechten Erfahrungen nicht wiederholen, dass wir also ein externer Partner sind, der sich für Sie lohnt. Nur dann macht Sinn, dass wir drüber sprechen, richtig?“"},
  {"p":"K","y":"Prinzip","t":"7:03","x":"Keine Ich-Sätze („Ich würde gerne mal einen Termin mit Ihnen vereinbaren, damit ich prüfen kann …“, „Ich mache das immer gerne so …“): Der Kunde gibt nur. Erst muss der Kunde profitieren, dann der Verkäufer – wie 639wCGS1SA4 (8:00)."}]},
"4OLqWQKmtPI": {"seg":"allgemein","target":"Agenturen allgemein","watch":false,"why":"","items":[
  ],"skip":"Nur Überblick über vier Stellschrauben (Sekretariat, Leitfaden, Einwandbehandlung, Stimme) plus Eigenwerbung; keine Formulierungen"},
"XamYlXN-yRo": {"seg":"allgemein","target":"B2B allgemein (Julians Top-3-Gesprächseinstiege)","watch":false,"why":"","items":[
  {"p":"K","y":"Opener","t":"8:01","x":"Platz 1, in rund 9 von 10 Fällen genutzt: „Darf ich gleich sagen, warum ich anrufe?“ (oder Tim Taxis' „Darf ich gleich zum Punkt kommen?“) – wie vePdGc0hxew und pW3HJaqKwoM. Betonung entscheidet, dass ein Ja kommt."},
  {"p":"K","y":"Opener","t":"4:00","x":"Platz 2: „Herr Meier, ich mach's ganz offen, ich möchte Sie gerne als Kunden gewinnen. Ist das grundsätzlich möglich oder lassen Sie sich gerade für nichts auf dieser Welt begeistern?“ – Antwort laut Julian immer: „Kommt drauf an, was Ihr Angebot ist.“ → „Okay, fair. Ich sag's Ihnen kurz in zwei Sätzen. Wenn es gar nicht relevant ist, legen wir auf, ansonsten können wir gerne tiefer ins Gespräch einsteigen. Einverstanden?“ Julian nutzt ihn selten, weil er dem verbreiteten „Das ist ein Kaltakquiseanruf …“ ähnelt."},
  {"p":"K","y":"Opener","t":"2:01","x":"Platz 3, bei schon einmal angerufenen Adressen: „Ich weiß gar nicht, ob Sie sich so spontan noch an meinen Namen erinnern können. Es ist schon ein bisschen her. Darf ich gleich sagen, was unser Thema war?“ – Julian nutzt ihn selten, weil er früheren Kontakt suggeriert; ohne echten Vorkontakt wäre es eine Lüge."},
  {"p":"K","y":"Prinzip","t":"0:00","x":"Nicht: „Das ist ein Kaltakquiseanruf, geben Sie mir 30 Sekunden oder wollen Sie gleich auflegen?“ – ein Teil sagt tatsächlich „auflegen“ und ist vor dem Angebot verloren. Ein Einstieg soll immer zu einem Ja führen."},
  {"p":"K","y":"Prinzip","t":"7:00","x":"Nach dem Einstieg entscheidet der „Nutzensatz“: Wer jetzt klassisch pitcht („Es geht um Recruiting …“), bekommt sofort Gegenwind."}]},
"RO3_qAB2WaY": {"seg":"allgemein","target":"B2B allgemein (Postsendung vor dem Anruf); HANDWERK: Negativbeispiel falscher Bewerber beim Elektriker","watch":false,"why":"","items":[
  {"p":"K","y":"Nachfassen","e":"Nach Postsendung/Broschüre","t":"8:02","x":"„Vielleicht können Sie mich gleich zuordnen. Ich hatte Ihnen die Tage unsere Broschüre zum Thema [ABC] per Post geschickt. Darf ich gleich sagen, warum ich mich heute telefonisch melde?“"},
  {"p":"K","y":"Nachfassen","t":"2:01","x":"Nach einer Postsendung nicht fragen „Ist sie denn angekommen?“ oder „Hat es Ihnen gefallen?“ – meist kommt „Weiß ich nicht, was wollen Sie denn?“ = Dämpfer gleich zum Start."},
  {"p":"K","y":"Organisation","t":"1:00","x":"Postsendung vorab verändert laut Julians Trainingserfahrung die Terminquote kaum, kostet aber Geld und Aufwand – gibt vor allem dem Anrufer Sicherheit."},
  {"p":"K","y":"Opener","t":"5:00","x":"Begrüßung wie pW3HJaqKwoM, Grußformel regional anpassen: „Hallo Herr Meier, hier ist [Vorname Nachname], grüß Sie“ – oder „Servus“, „Moin“, „Grüezi“."},
  {"p":"K","y":"Prinzip","t":"12:00","x":"Keine falsche Erwartung wecken: Negativbeispiele „Die Stelle bei Ihnen als Elektriker, ist die noch offen?“ (Anrufer ist kein Bewerber) oder beim Küchenstudio „Haben Sie auch einen Showroom?“ (Anrufer ist kein Kunde) – die Enttäuschung danach („schon wieder so eine Agentur“) zerstört den Start."}]},
"wMeFVvX8Wc0": {"seg":"allgemein","target":"Agenturen (Recruiting, Kundengewinnung) allgemein","watch":false,"why":"","items":[
  {"p":"K","y":"Prinzip","t":"7:02","x":"Keine herausfordernden Suggestivfragen wie „Herr Meier, aber mal ganz ehrlich, wenn ich Ihnen da jetzt Kandidaten vor die Tür stelle, die würden Sie ja nicht wegschicken, oder?“ – logisch richtig, wirkt aber manipulativ und erzeugt Misstrauen."},
  {"p":"K","y":"Prinzip","t":"0:00","x":"„Kein Interesse“, „Schicken Sie mir was zu“, „schlechter Zeitpunkt“ sind oft Vorwände aus fehlendem Vertrauen, obwohl Bedarf da ist – wie EsK12QRwpU4."}]},
"MA_C7LHCsaY": {"seg":"Handwerk","target":"Recruiting-Agentur → HANDWERK, Pflege, Industrie, Steuerkanzleien, Zahnärzte (Analyse eines Follower-Leitfadens)","watch":false,"why":"","items":[
  {"p":"K","y":"Opener","t":"2:00","x":"Begrüßung „Hallo Herr Meier, hier ist [Vorname Nachname], ich grüße Sie“ und „Darf ich gleich sagen, warum ich anrufe?“ empfiehlt Julian 1:1 – wie pW3HJaqKwoM."},
  {"p":"K","y":"Opener","t":"7:00","x":"Negativbeispiel für Handwerk und andere überlaufene Zielgruppen: „Wir finden qualifizierte Mitarbeiter für Unternehmen wie Ihres, aber ich will jetzt nicht der 17. sein, der Sie mit dem Thema nervt. Darf ich Ihnen eine kurze Frage stellen?“ – Standardsatz, den jeder zweite sagt; die Einwandvorwegnahme ist zu schwach, die Zahl reizt („700 haben mich schon angerufen“)."},
  {"p":"K","y":"Opener","t":"9:00","x":"Bei selten angerufenen Themen funktioniert die Vorwegnahme: „Es geht um eine Industriesoftware, aber ich will jetzt gar nicht Ihre Zeit unnötig in Anspruch nehmen. Darf ich stattdessen eine kurze Frage stellen?“"},
  {"p":"K","y":"Opener","t":"11:00","x":"Negativbeispiel Pitch: „Wir hören immer wieder von unseren Partnern, dass sie bei der Mitarbeitersuche zwei Schwierigkeiten haben … Sind Sie grundsätzlich offen für einen kurzen Austausch, wenn ich Ihnen zeigen kann, wie wir genau diese Probleme lösen?“ – Julian: offensichtliche Probleme langweilen, „Wir hören immer wieder“ wirkt unsicher, „kurzer Austausch“ hat keinen Wert für den Kunden."},
  {"p":"K","y":"Prinzip","t":"16:00","x":"Ziel des Pitches: Der Gesprächspartner fragt von sich aus nach („Wie meinen Sie das genau?“, „Wie soll das funktionieren?“, „Was kostet so was?“) – gebende statt nehmende Energie. Passt zu 639wCGS1SA4: Rückfragen sind Kaufsignale."},
  {"p":"K","y":"Prinzip","t":"19:00","x":"Vor der Terminfrage muss der Kunde einen Grund für das Ja haben (Nutzen) – bzw. es muss ihm schwerfallen, Nein zu sagen."}]},
"jP9LIeuszbc": {"seg":"allgemein","target":"Agenturen allgemein","watch":false,"why":"","items":[
  ],"skip":"Nur These „Schlagzahl verstärkt, was da ist“ und Quoten ohne Beleg; keine Formulierungen"},
"ySUKEomccBI": {"seg":"allgemein","target":"Verkäufer selbst (Telefonhemmungen)","watch":false,"why":"","items":[
  ],"skip":"Mindset (Hemmungen über positive Erfahrungen abbauen) und Coaching-Werbung; einziger Praxishinweis: ab ca. 10. Dezember bis Mitte Januar kaum Termine – vorher akquirieren"},
"hKE2vnfiWAg": {"seg":"allgemein","target":"Agenturen (Social Recruiting, Webdesign) allgemein","watch":false,"why":"","items":[
  {"p":"K","y":"Prinzip","t":"2:00","x":"Reframing wirkt nur, wenn das Gespräch vorher entspannt ist – wie KKvUr--VrQE. Bei gutem Aufbau kommen weiche, meist ehrliche Einwände (Recruiting-Beispiel: „Wir haben gerade tatsächlich einen ganz guten Bewerberzulauf, im Moment würden wir das erstmal abwarten“); bei schlechtem Aufbau harte Ablehnung („Sie sind schon der Zehnte“) und Auflegen, dann hilft keine Technik."},
  {"p":"K","y":"Einwand","e":"Haben intern schon eine gute Lösung","t":"7:00","x":"Reframing wie uQhEkID92pI; typische Kundenantwort im entspannten Gespräch: „Ja, gut. Kommt drauf an, was Sie denn da anbieten.“ – bei „Haben schon Partner“: „Ja, klar, dann schon. Vergleichen kann man immer mal.“"}]},
"0iUoVRRAc50": {"seg":"allgemein","target":"Verkäufer selbst (Telefonhemmungen)","watch":false,"why":"","items":[
  ],"skip":"Mindset (Gedanken → Emotion → Handlung, klein starten) und Coaching-Werbung; keine Formulierungen"},
"FLDVG9syiUc": {"seg":"Handwerk","target":"HANDWERK: Social-Recruiting-Agentur → Handwerksbetriebe (Analyse eines echten Leitfadens)","watch":true,"why":"Wichtigstes Handwerk-Video bisher: Leitfaden für Handwerksbetriebe Satz für Satz zerlegt; Tonalität der Begrüßung (zu überschwänglich vs. gelangweilt) vorgeführt (2:00–4:01)","items":[
  {"p":"K","y":"Opener","t":"2:00","x":"Begrüßung nicht überschwänglich („Schönen guten Tag …“ riecht nach Verkäufer) und nicht gelangweilt (Gefahr bei tiefer Männerstimme): sympathisch-neutral „Guten Tag Herr Meier, hier ist der [Vorname Nachname], grüß Sie“ – Grußformel am Ende regional (Servus, Moin), wie pW3HJaqKwoM."},
  {"p":"K","y":"Prinzip","t":"6:01","x":"Namen des Gesprächspartners nicht ständig wiederholen („Herr Müller, Herr Müller …“) – alter Verkäufertrick, wirkt manipulativ und erzeugt Misstrauen."},
  {"p":"K","y":"Opener","t":"5:01","x":"Negativbeispiel: „Herr Müller, ich komme mal gleich zum Punkt, weil mir Ihre und meine Zeit sehr wertvoll ist.“ – Aussage statt Frage: diktiert den Ablauf, Floskel, der Kunde antwortet nicht → Monolog. Besser die Frage „Darf ich gleich sagen, warum ich anrufe?“ (holt aktive Zustimmung). Hinweis: Tim Taxis' „Darf ich gleich zum Punkt kommen?“ ist als Frage weiterhin okay (vePdGc0hxew)."},
  {"p":"K","y":"Opener","t":"12:02","x":"Negativbeispiel Handwerk-Pitch: „Wir unterstützen Handwerksunternehmen dabei, die passenden Fachkräfte einzustellen und sich selbst als attraktiver Arbeitgeber in der Region zu positionieren. Wir sind kein Personalvermittler, sondern haben direkt Wege, über die wir passende Kandidaten für Sie ansprechen … Ist denn die Stelle als Elektriker bei Ihnen noch vakant?“"},
  {"p":"K","y":"Prinzip","t":"13:00","x":"Nichts unterstellen: „attraktiver Arbeitgeber werden“ / „super Außendarstellung bekommen“ (auch Webdesign) sagt zwischen den Zeilen „aktuell ist es schlecht“ → Handwerker geht in Widerstand („Familienunternehmen seit 45 Jahren, uns kennt hier jeder, wir sind Platzhirsch“)."},
  {"p":"K","y":"Prinzip","t":"14:00","x":"„Wir sind kein Personalvermittler“ ist überflüssig: Handwerker wissen, dass Social-Recruiting-Agenturen über Facebook/Instagram arbeiten, und denken sofort an versenktes Geld und fehlende Einstellungsgarantie. Die Frage nach der ausgeschriebenen Stelle beantworten sie mit einer Lüge („nein“), weil sie genervt sind."},
  {"p":"K","y":"Einwand","e":"Kein Interesse / kein Bedarf / voll besetzt / gerade eingestellt","t":"19:01","x":"Alles derselbe Einwand mit anderer Begründung → gleich behandeln. Negativbeispiel: „Danke, dass Sie das gleich so offen ansprechen. Aber einen richtig guten Kandidaten würden Sie doch nicht einfach zur Konkurrenz schicken, oder?“ – Lob für einen Einwand ist unglaubwürdig, „aber“ erzeugt Widerstand, Suggestivfrage provoziert die Lüge „Wir sind voll“."},
  {"p":"K","y":"Prinzip","t":"23:01","x":"Wenn Handwerker anschreien, unterbrechen oder auflegen: nicht Zielgruppe oder Angebot wechseln – die Reaktion ist eine Antwort auf den eigenen Leitfaden und Tonfall."},
  {"p":"K","y":"Terminvereinbarung","t":"28:01","x":"Negativbeispiel: „Dann würde ich vorschlagen, wir verabreden uns für die Tage. Wir machen das immer gerne per Videocall, kann ich Ihnen gleich unsere Methode vorstellen.“ (nur eigenes Interesse). Besser: „Herr [Nachname], damit Sie [Ergebnis XY] bekommen, ist es sinnvoll, dass wir erst [Schritt 1] und dann [Schritt 2] machen.“"},
  {"p":"K","y":"Prinzip","t":"16:00","x":"Pitch als „Nutzensatz“ bauen, der Rückfragen auslöst („Wie läuft das genau?“) – wie MA_C7LHCsaY. Wer von sich aus mehr wissen will, hat Eigeninteresse am Termin und erscheint auch."}]},
"-3B7Rt2zDGw": {"seg":"allgemein","target":"Energieberater (Strom/Gas B2B) vs. Agenturen; Handwerk nur als überlaufene Zielgruppe erwähnt","watch":false,"why":"","items":[
  ],"skip":"Nur Marktvergleich (Energievertrieb hat schwächer geschulte Konkurrenz als Agenturen); keine Formulierungen"},
"pacRsnbOZ2o": {"seg":"allgemein","target":"B2B allgemein (Sekretariat)","watch":true,"why":"Tonalität im Sekretariat vorgeführt: überschwänglicher Singsang vs. verbindlich-selbstverständlich (5:01–8:01)","items":[
  {"p":"K","y":"Sekretärin","t":"7:00","s":1,"x":"„Einmal bitte weiter zu [Vorname Nachname], [Vorname Nachname] ist dran. Ich bleib in der Leitung. Danke schön.“ – sehr verbindlich und straight einfordern, als wäre es das Normalste der Welt; nicht unhöflich, aber auch nicht bittend. Kurzform von zdFAzni-M1s."},
  {"p":"K","y":"Prinzip","t":"5:01","x":"Drei Fehler, an denen die Sekretärin den Verkäufer erkennt: 1. sie mit ihrem Namen ansprechen („Hallo Frau Meier …“ – macht kein normaler Anrufer), 2. den eigenen Firmennamen nennen (unbekannter Name = neuer Anbieter), 3. überschwänglich freundlicher Singsang. ⚠️ Widerspricht dem älteren vePdGc0hxew (5:00/6:01), wo Julian Name + Firma noch akzeptierte – diese neuere Empfehlung gilt."},
  {"p":"K","y":"Prinzip","t":"8:01","x":"„Worum geht es denn?“ hat drei mögliche Gründe: Verkäufer-Check, Stichwort fürs Durchstellen (sie hat schon entschieden) oder der Chef ist nicht da und sie will helfen. Bei der Frage nicht unsicher werden oder stammeln – genau das macht sie misstrauisch. Selbstsicheren Ton halten."},
  {"p":"K","y":"Prinzip","t":"2:00","x":"Mail an info@ ist der „virtuelle Papierkorb des Unternehmens“ – keine Zeit in solche Mails investieren."}]},
"Du5mYM2s4io": {"seg":"allgemein","target":"Agenturen allgemein (Reframing mit Formulierungen)","watch":false,"why":"","items":[
  {"p":"K","y":"Einwand","e":"Zu teuer","t":"8:01","x":"„Okay, das heißt nur, wenn wir ein Angebot machen, was zu Ihnen ins Budget passt, dann macht Sinn, dass wir konkret drüber schauen, richtig?“ – Reframing wie 639wCGS1SA4."},
  {"p":"K","y":"Einwand","e":"Schlechte Erfahrungen gemacht","t":"8:01","x":"Variante: „Das heißt nur, wenn wir sicherstellen, dass sich die schlechten Erfahrungen nicht wiederholen, nur dann macht Sinn, dass wir der Sache noch mal eine zweite Chance geben.“"},
  {"p":"K","y":"Terminvereinbarung","e":"Haben schon einen Partner","t":"7:01","x":"Nach dem Ja: „Okay, dann lassen Sie uns doch mal schauen, was die Tage passt, dass wir den Vergleich mal machen können.“ – bei „intern“: „… dann können wir mal schauen, welche sinnvolle Ergänzung wir da vielleicht herstellen können.“"},
  {"p":"K","y":"Einwand","e":"Haben schon einen Partner","t":"9:00","x":"Negativbeispiel (klassische Technik, Julian lehnt sie ab): „Danke, dass Sie das gleich so offen sagen … ein Mann von Ihrem Format hat natürlich schon einen Partner … Genau deshalb macht es Sinn: Entweder Sie bekommen die Bestätigung oder ein Angebot für einen besseren Partner. Sind Sie offen für einen besseren Partner in der Zukunft?“ – Schmeichelei, „genau deshalb“ und Suggestivfrage wirken manipulativ."},
  {"p":"K","y":"Prinzip","t":"6:01","x":"Reframing deckt laut Julian 90–95 % der Einwände ab; für den Rest gibt es eine zweite Technik, die er nur im Training zeigt."}]},
"p9rQHNxk-Yw": {"seg":"allgemein","target":"Agenturen allgemein (Beispiel Recruiting-Plattform)","watch":false,"why":"","items":[
  {"p":"K","y":"Prinzip","t":"1:01","x":"Am Telefon über das Was sprechen (Ergebnis, gelöstes Problem, erreichtes Ziel), nie über das Wie (wie die Lösung funktioniert). Wer das Wie erklärt, gibt „70 von 500 Puzzleteilen“ raus → „Schicken Sie mal Unterlagen“ oder vorschnelles Nein."},
  {"p":"K","y":"Rückfrage","e":"Wie machen Sie das genau?","t":"5:01","x":"Wie-Frage nicht beantworten, sondern als Überleitung nutzen: „Ja, ist eine gute Frage, will ich Ihnen gerne im Detail erklären. Wie sieht's denn bei Ihnen aus, morgen am Vormittag oder ein bisschen später am Tag? Dann zeige ich es Ihnen mal.“ – Präzisierung zu 639wCGS1SA4 („kurz beantworten“): Die Wie-Frage gar nicht beantworten."}]},
"jAQ3TLbFTck": {"seg":"allgemein","target":"B2B allgemein (Show-up-Rate); Bedarfsfragen am Beispiel Recruiting","watch":false,"why":"","items":[
  {"p":"K","y":"Terminvereinbarung","t":"3:00","x":"Termin so nah wie möglich legen: am besten am gleichen Tag (vormittags anrufen, nachmittags Termin), sonst am nächsten Tag – je weiter in der Zukunft, desto häufiger fällt er aus."},
  {"p":"K","y":"Terminvereinbarung","t":"5:00","x":"Nicht offen fragen „Wann passt es denn die Tage?“ (Kunde springt gedanklich zwei Wochen weiter). Stattdessen: „Alles klar, dann lassen Sie uns gerne mal schauen, wann es die Tage passt. Wie sieht's denn spontan morgen bei Ihnen aus? Am Vormittag oder ein bisschen später am Tag?“ – oder: „Wie sieht's denn heute am Nachmittag spontan bei Ihnen aus? 15 Uhr würde bei mir noch ganz gut klappen, 16 Uhr geht auch noch.“ Ersetzt die offene Frage aus vePdGc0hxew (37:00)."},
  {"p":"K","y":"Terminvereinbarung","e":"Morgen passt nicht","t":"5:00","x":"„Okay, kein Problem. Und übermorgen?“ – immer nur einen Tag weitergehen („Leitplanken“), nie die nächsten zwei Wochen öffnen."},
  {"p":"K","y":"Prinzip","t":"6:01","x":"Ein Termin für morgen wirkt nicht so, als hätte man nichts zu tun – diese Sorge ist unbegründet."},
  {"p":"K","y":"Terminvereinbarung","t":"7:01","x":"Nach der Zusage zwei Bedarfsfragen nachschieben: „Herr Meier, ganz kurz, bevor wir auflegen, ich habe noch schnell zwei Fragen, weil dann sind wir am Donnerstag ein bisschen schneller direkt beim Thema und ich kann was vorbereiten.“ Recruiting-Beispiel: „Suchen Sie jetzt nur eine Person auf der Stelle oder würden Sie potenziell auch eine zweite einstellen?“ / „Würden die per sofort bei Ihnen anfangen können oder gibt's eine Vorlaufzeit?“"},
  {"p":"K","y":"Terminvereinbarung","t":"8:00","x":"Auf die Antwort Relevanz bestätigen: „Oh ja, das ist ja perfekt, noch besser, dann weiß ich Bescheid. Donnerstag erkläre ich Ihnen genau, wie wir das machen … In dem Fall passt es noch besser. Dürfen Sie gespannt sein auf Donnerstag.“"},
  {"p":"K","y":"Organisation","t":"10:00","x":"Nach der Zusage recherchieren viele (Website, Social Media, Bewertungen, KI). Passt das Bild nicht zur Erwartung aus dem Telefonat, springen sie ab – eigenen Online-Auftritt prüfen."}]},
"9NelY2UIGy4": {"seg":"allgemein","target":"Agenturen allgemein (nicht verkäuferisch wirken)","watch":false,"why":"","items":[
  {"p":"K","y":"Prinzip","t":"3:00","x":"Nicht verbergen, dass man etwas verkaufen will, und keine „Kumpelnummer“ – der Angerufene merkt das sofort und wird misstrauisch. Offen sein, aber sein Interesse in den Mittelpunkt stellen."},
  {"p":"K","y":"Opener","t":"5:00","x":"Negativbeispiel: „Herr Meier, ich wollte Sie mal kurz anrufen, weil wir sind, wir haben, wir können … und die nächsten Tage würde ich gerne mal mit Ihnen prüfen, ob wir vielleicht ein potenzieller Partner für Sie sein können.“ – nur eigenes Interesse, wie uQhEkID92pI."},
  {"p":"K","y":"Prinzip","t":"9:01","x":"Leitfaden nutzen, aber so sprechen, dass man es nicht merkt – hörbares Ablesen oder Aufsagen wirkt manipulativ und löst Einwände aus."},
  {"p":"K","y":"Prinzip","t":"10:01","x":"Keine offenen Fragen, bevor der Kunde etwas bekommen hat (Negativbeispiel direkt nach dem Pitch: „Wie haben Sie denn das Thema Social Media Marketing bei sich schon gelöst?“) – bringt ihn in die Geberrolle. ⚠️ Beim Zusammenführen gegen Bedarfsfragen wie aaWn8bLoCQg abgrenzen; die kommen dort erst nach Erlaubnis und Thema."},
  {"p":"K","y":"Prinzip","t":"10:01","x":"Keine Suggestivfragen („Wenn da jetzt noch mal so ein guter Bewerber käme, würden Sie den doch nicht wegschicken, oder?“) – provoziert Trotz, wie wMeFVvX8Wc0."},
  {"p":"K","y":"Prinzip","t":"14:01","x":"Nicht auf jede Antwort „super“ oder „perfekt“ sagen und den Namen nur dezent nutzen (wie FLDVG9syiUc) – typisches Verkäuferverhalten."}]},
"_6-9rCIOrnM": {"seg": "allgemein", "target": "Selbstständige/Agenturen (Hemmungen beim Telefonieren)", "watch": false, "why": "","items":[
  {"p": "K", "y": "Organisation", "t": "4:00", "x": "Akquise als Quotenspiel sehen: Ein Nein ist „einer von den Gesprächen, die eh kein Termin werden“ – das nimmt die Nervosität vor dem nächsten Anruf."},
  {"p": "K", "y": "Organisation", "t": "12:00", "x": "Bei Hemmungen nicht mit 150 Anwahlen starten, sondern klein: heute 1–5 Anwahlen, dann täglich steigern."}]},
"CEeHQqm-Hz8": {"seg": "allgemein", "target": "Agenturen (Recruiting, Webdesign, Werbeanzeigen) → KMU", "watch": false, "why": "","items":[
  {"p": "K", "y": "Prinzip", "t": "1:00", "x": "Am Anfang keine offenen Fragen, sondern Nutzensatz + geschlossene Frage, die so formuliert ist, dass der Kunde „kaum Nein sagen kann“. Offene Fragen bringen den Fremden in die Geberrolle („erst abheben, bevor du eingezahlt hast“)."},
  {"p": "K", "y": "Opener", "t": "2:00", "x": "Negativbeispiel: „Hallo Herr Meier, hier ist der Julian Mahnken, ich grüße Sie. Wir sind spezialisiert auf den Bereich Recruiting, das heißt, wir machen ABCDE. Wie haben Sie das denn aktuell bei sich gelöst?“"},
  {"p": "K", "y": "Opener", "t": "6:00", "x": "Negativbeispiel „über den Kunden stellen“: „Ich war gerade mal auf Ihrer Karriereseite … da gibt's viel Optimierungspotenzial, deswegen rufe ich Sie an.“ / „Ich habe mir mal angeguckt, welche Werbeanzeigen Sie aktuell schalten …“ – provoziert aktiv Ablehnung. Bestätigt: Website-Mängel nicht als Einstieg."},
  {"p": "K", "y": "Opener", "t": "7:02", "x": "Negativbeispiel „klein machen“: „Da würde ich gerne die nächsten Tage einfach mal mit Ihnen in den Austausch gehen, dann könnten wir einfach mal gucken, inwieweit wir da vielleicht miteinander matchen können …“ – könnte/hätte/würde, wird nicht ernst genommen."},
  {"p": "K", "y": "Prinzip", "t": "8:00", "x": "Augenhöhe + Relevanz (über den Nutzensatz). Erst wenn beides steht, sind offene Fragen in Ordnung – nicht am Anfang."}]},
"G3rnGgSHtEI": {"seg": "allgemein", "target": "Vlog Tagesablauf (Trainer)", "watch": false, "why": "","items":[
  {"p": "K", "y": "Sekretärin", "t": "4:00", "x": "„Würden Sie mich bitte gleich einmal zum [Vorname Nachname] weiterstellen, dann richten Sie gerne aus, der Julian Mahnken ist dran.“ – wie aaWn8bLoCQg."},
  {"p": "K", "y": "Organisation", "t": "3:00", "x": "Termin erscheint nicht (No-Show): kurz telefonisch nachfassen, dann die geblockte Zeit sofort für Kaltakquise nutzen."},
  {"p": "K", "y": "Einwand", "e": "Kein Bedarf / Stelle so gut wie besetzt", "t": "12:00", "x": "Beides ist derselbe Einwand („kein Bedarf“) mit anderer Begründung → gleich behandeln (wie Nr. 14 @19:01)."}]},
"lmTt3IZDEyI": {"seg": "allgemein", "target": "Social-Recruiting-Agenturen", "watch": false, "why": "", "skip": "Geschäftsmodell/Eigenwerbung (Umsatzbeispiele, Recruiting ist Evergreen u. a. im Handwerk); keine Formulierungen","items":[
]},
"0WP0MGE_TH0": {"seg": "allgemein", "target": "Agenturen (Wahl von Angebot und Zielgruppe)", "watch": false, "why": "","items":[
  {"p": "K", "y": "Organisation", "t": "2:00", "x": "Bewährte Zielgruppe wählen statt „Einhorn“ suchen; z. B. Recruiting hat sich bei Handwerk, Pflege, Zahnärzten, Industrie bewährt. Unterschied zu erfolgreichen Agenturen ist fast immer der Vertrieb, nicht das Angebot."},
  {"p": "K", "y": "Prinzip", "t": "6:01", "x": "Man ist nie der Erste, eher der 50.–100. Anrufer zum Thema; Standard-Opener („Das ist ein Kaltakquise-Anruf …“) sind verbrannt – sich durch eigene Formulierung abheben (wie Nr. 1)."}]},
"ZQYRS2SrCy0": {"seg": "Handwerk", "target": "Webdesigner → Handwerksbetriebe", "watch": false, "why": "","items":[
  {"p": "K", "y": "Prinzip", "t": "3:00", "x": "Handwerker sehen eine Website eher als „nice to have“; die eigentliche Hürde ist, Nutzen und Dringlichkeit klarzumachen – aber nicht über Tadel („Ich war gerade auf Ihrer Webseite, da gibt's ganz dringenden Handlungsbedarf“)."},
  {"p": "K", "y": "Prinzip", "t": "6:01", "x": "Gesprächsaufbau in vier Zielen: Aufmerksamkeit bekommen → fürs Gespräch öffnen → Vertrauen aufbauen → Interesse und Bedarf wecken."},
  {"p": "K", "y": "Prinzip", "t": "7:01", "x": "Das Wort „Webseite“ muss man nicht ersetzen, aber der Nutzensatz muss so gebaut sein, dass er seinen Nutzen wirklich versteht – bloß „wir bringen Ihnen neue Kunden / mehr Anfragen / neue Mitarbeiter“ reicht nicht. ⚠️ Betrifft den 🛠-Nutzensatz-Entwurf im Zwischenstand."},
  {"p": "K", "y": "Organisation", "t": "11:00", "x": "Webdesign + Handwerksbetriebe ist eine bewährte Kombination; man ist „der 51., der anruft, aber der erste, der einen Termin vereinbart“."}]},
"61ZlLVM0uS0": {"seg": "allgemein", "target": "alle Branchen, B2B (Beispiele Recruiting/Elektrobetrieb, Küchenstudio)", "watch": false, "why": "","items":[
  {"p": "K", "y": "Opener", "t": "1:00", "x": "„Hallo Herr Meier, hier ist der Julian Mahnken, grüß Sie.“ – Reihenfolge bewusst: Name des Gegenübers (Aufmerksamkeit), „hier ist“ statt „mein Name ist“ (Nähe), Vor- und Nachname, „grüß Sie“ am Ende provoziert eine Grußerwiderung → Dialog statt Monolog. Bestätigt Nr. 390."},
  {"p": "K", "y": "Opener", "t": "4:00", "x": "Negativbeispiel Monolog direkt nach dem Gruß: „Herr Meier, ich rufe Sie heute an, weil wir haben, wir können, wir machen …“ – fühlt sich wie Überfall an."},
  {"p": "K", "y": "Opener", "t": "4:00", "x": "Abgeraten: „Das ist ein Kaltakquise-Anruf, wollen Sie gleich auflegen oder geben Sie mir 30 Sekunden?“ (ein Teil legt direkt auf, bevor er das Angebot hört) und Gags wie „Wenn ich die Farbe Ihrer Unterhose errate, darf ich dann pitchen?“ (unseriös im B2B)."},
  {"p": "K", "y": "Opener", "t": "8:00", "x": "Negativbeispiel falsche Erwartung: „Ich wollte mal kurz fragen, bei Ihnen im Küchenstudio, kann man da die Küchen nur online angucken oder gibt's auch einen Showroom?“ → danach „ganz offen, ich bin selber kein Kunde …“ = Süßigkeit hinhalten und wegziehen (wie Nr. 7 @12:00)."},
  {"p": "K", "y": "Opener", "t": "10:00", "x": "„Darf ich gleich sagen, warum ich anrufe?“ – Abwandlung von Tim Taxis' „Darf ich gleich zum Punkt kommen?“. Weckt Neugier ohne falsche Erwartung; der Kunde entscheidet selbst fürs Gespräch und öffnet sich dadurch. Funktioniert laut Julian immer, wenn richtig betont."},
  {"p": "K", "y": "Prinzip", "t": "13:01", "x": "Begrüßung + Erlaubnisfrage sind branchenunabhängig; individuell ist erst der folgende Nutzensatz. Reagiert der Kunde mit „Wie machen Sie das genau?“, ist das der Punkt für die Terminvereinbarung."}]},
"J-bnKLumcqs": {"seg": "KMU", "target": "Webdesigner → kleiner Betrieb mit Stammkunden (Nachfass-Anruf nach Postsendung)", "watch": true, "why": "Echtes Telefonat mit Analyse: unsichere Stimme, Gegenfrage übernimmt die Führung, typischer Einwand „Website brauchen wir nicht, haben Stammkunden“","items":[
  {"p": "K", "y": "Nachfassen", "t": "1:00", "x": "Negativbeispiel: „Ich hab Ihnen vor ein paar Tagen was mit der Post geschickt … darf ich dazu eine kurze Frage mal stellen?“ – unsicher, Stimme geht hoch → Kunde verwirrt: „Was haben Sie mir denn da mit der Post geschickt?“"},
  {"p": "K", "y": "Prinzip", "t": "3:00", "x": "Antwortet der Kunde mit einer Gegenfrage, übernimmt er die Führung („Wer fragt, der führt“). Ursache hier: Unsicherheit in Stimme und Text. Was man an Unsicherheit reingibt, kommt als Verwirrung zurück."},
  {"p": "K", "y": "Opener", "t": "4:00", "x": "Negativbeispiel: „Ich bin Spezialist für Webseiten, aber ich will Sie gar nicht großartig mit Ihrer Zeit beanspruchen. Ich würde Ihnen nur eine kurze Frage dazu stellen.“ – Konjunktive, macht sich klein."},
  {"p": "K", "y": "Organisation", "t": "4:00", "x": "Prospekte, Pakete, Schokolade vorab: kann man machen, wirkt aber werbend und hat in umkämpften Märkten meist keinen echten Effekt – Aufwand und Kosten in der Regel sparen."},
  {"p": "K", "y": "Einwand", "e": "Website ist für uns nicht interessant, wir haben Stammkunden, über die Seite kommen nur Schein-Anfragen", "t": "6:01", "x": "Negativbeispiel: dagegen argumentieren („Und unsere Kunden, wenn die dann sehen, wie professionell sie in ihrer Region wahrgenommen werden …“) → Widerstand, Kunde final verloren. Ursache laut Julian: vorher keine Relevanz erzeugt. Eine gute Antwort zeigt das Video nicht (Teil 2 nur angekündigt)."}]},
"h-38m1btw4c": {"seg": "Handwerk", "target": "Webdesigner → Handwerksbetriebe", "watch": false, "why": "","items":[
  {"p": "K", "y": "Prinzip", "t": "3:01", "x": "Handwerker werden mehrmals täglich mit ähnlichen Leitfäden angerufen und sind „vom Persönlichkeitstyp sehr direkt“ – Einstiege von oben herab („Ich war gerade auf Ihrer Webseite, da müssen wir mal drüber reden“) oder kleinlaut funktionieren dort besonders schlecht (wie Nr. 22, Nr. 1)."},
  {"p": "K", "y": "Organisation", "t": "12:00", "x": "Webdesign fürs Handwerk weiter sinnvoll; nicht die Zielgruppe wechseln, sondern sich in der Akquise abheben."}]},
"QKqnt3MAvr0": {"seg": "allgemein", "target": "Selbstständige (Hemmungen, Motivation)", "watch": false, "why": "", "skip": "Motivation/Mindset und Eigenwerbung; einzige Regel (Reaktion des Kunden folgt aus dem eigenen Satz) schon in Nr. 12 erfasst","items":[
]},
"D7HDIGlf6p4": {"seg": "allgemein", "target": "alle (Angst vor Abmahnung/aggressiven Reaktionen)", "watch": false, "why": "","items":[
  {"p": "K", "y": "Organisation", "t": "2:00", "x": "Abmahnungen kommen in der Praxis kaum vor; der einzige bekannte Fall (nur Drohung) kam von einer Kanzlei → Julian rät, keine Rechtsanwälte anzurufen. Ausdrücklich keine Rechtsberatung."},
  {"p": "K", "y": "Prinzip", "t": "3:01", "x": "Aggressive Reaktionen sind Reaktionen auf Druck, Dominanz oder Argumentieren gegen den Standpunkt des Kunden – Wording und Stimme ändern, nicht die Zielgruppe (wie Nr. 12)."}]},
"gEbx_BUaVnk": {"seg": "allgemein", "target": "Agenturen (Webdesign, Recruiting) → KMU", "watch": false, "why": "","items":[
  {"p": "K", "y": "Einwand", "e": "Schlechte Erfahrungen gemacht", "t": "2:02", "x": "„Okay, das heißt nur, wenn wir sicherstellen, dass sich die schlechten Erfahrungen nicht wiederholen – nur dann würden Sie der Sache überhaupt eine zweite Chance geben, stimmt's?“ (Variante zu Nr. 53; übrige Reframings wie dort)"},
  {"p": "K", "y": "Prinzip", "t": "3:01", "x": "Reframing-Logik: Der Einwand ist ein Problem → man schlägt eine Lösung im Sinne des Kunden vor; darum ist die logische Antwort „Ja“. Bei „intern“ nur „sinnvolle Ergänzung“, nie „besser als Ihre Leute“."},
  {"p": "K", "y": "Terminvereinbarung", "t": "6:01", "x": "Direkt nach dem Ja auf das Reframing: „Okay, dann lassen Sie uns mal schauen, wann es die Tage passt, dass wir drüber sprechen.“ Nicht weiterargumentieren oder herumreden – die Unsicherheit provoziert sonst den nächsten Einwand („Schicken Sie mal Unterlagen“)."}]},
"mC1M_WIBjQQ": {"seg": "allgemein", "target": "alle Branchen, B2B", "watch": false, "why": "","items":[
  {"p": "K", "y": "Opener", "t": "7:00", "x": "Begrüßung und „Darf ich gleich sagen, warum ich anrufe?“ wie 61ZlLVM0uS0, gleiche Begründung."},
  {"p": "K", "y": "Prinzip", "t": "9:01", "x": "Firmennamen weglassen (fremde Info = Distanz); nur nennen, wenn ausdrücklich gefragt (laut Julian ca. 1 von 500 Gesprächen). „Grüß Sie“ ist unproblematisch, Servus/Moin auch."},
  {"p": "K", "y": "Prinzip", "t": "11:01", "x": "Lächeln beim Begrüßen, vor allem bei tiefer (Männer-)Stimme: tief-neutral klingt nach „potenzieller Gefahr“, herzlich-sympathisch nach „sicher“."}]},
"_dFxUto_JYs": {"seg": "allgemein", "target": "Vlog Routinen (Trainer, eigenes Vertriebsteam)", "watch": false, "why": "","items":[
  {"p": "K", "y": "Organisation", "t": "3:17", "x": "Täglich 5–10 Min. Einwandtraining (allein vorlesen oder im Rollenspiel) für die Klassiker: kein Interesse, kein Bedarf, schicken Sie Unterlagen, keine Zeit, haben schon Partner, machen wir intern, schlechte Erfahrung – wie Standardsituationen im Fußball."},
  {"p": "K", "y": "Organisation", "t": "0:00", "x": "Morgens Tagesziel setzen (Termine/Abschlüsse), abends prüfen: erreicht? Was machen wir ab morgen besser?"},
  {"p": "T", "y": "Prinzip", "t": "7:00", "x": "Im Verkaufsgespräch den Entscheider nicht auf ein Podest stellen (Ehrfurcht, Komplimente, „wow, das ist ja krass“) – dadurch macht man sich selbst klein und verliert die Augenhöhe."}]},
"J_M2nwXoCOk": {"seg": "allgemein", "target": "Personalvermittlung → Geschäftsführer (Coaching-Call)", "watch": false, "why": "","items":[
  {"p": "K", "y": "Prinzip", "t": "9:00", "x": "Status entsteht in zwei Schritten: 1. Verhalten/Stimme in den ersten Sätzen (selbstsicher, sympathisch, weder drüber noch klein = Augenhöhe), 2. Relevanz des Themas (über den Nutzensatz)."},
  {"p": "K", "y": "Prinzip", "t": "11:00", "x": "Als Verkäufer klingen, nicht wie ein Geschäftsführer oder Arzt – rollenkongruentes Verhalten empört keinen; dominantes Auftreten macht skeptisch."},
  {"p": "K", "y": "Prinzip", "t": "15:00", "x": "Ist das Thema gerade irrelevant (z. B. keine offene Stelle, Firma schließt), darf das Gespräch enden; Relevanz ggf. später über andere Anlässe neu herstellen."},
  {"p": "K", "y": "Organisation", "t": "2:00", "x": "Respekt vor Geschäftsführern abbauen: Ein irrelevanter Anruf kostet ihn 60 Sekunden und ist sofort vergessen; erfolgreiche Unternehmer haben selbst schon aus Kaltakquise gekauft."}]},
"JziWDNtfZX0": {"seg": "allgemein", "target": "Inhouse-Training Firmenreise-Anbieter (B2B-Verkaufspräsentation)", "watch": false, "why": "","items":[
  {"p": "T", "y": "Gesprächseinstieg", "t": "0:00", "x": "Keine Vorstellungsrunde mit Werdegang, Gründergeschichte, Mission („schönes Büro, gerne Kuchen“) und kein „Stellen Sie sich doch mal bitte vor“ – der Kunde will wissen, was er davon hat."},
  {"p": "T", "y": "Gesprächseinstieg", "t": "2:00", "x": "Selbstvorstellung mit Kundennutzen: „Mein Name ist Julian Mahnken, ich mache seit 17 Jahren Telefonakquise, dieses Unternehmen gibt es seit 7 Jahren und wir sind gerade auf Branchen wie Ihre spezialisiert. Das heißt, es war kein Zufall, dass wir gezielt Sie akquiriert haben … mit Unternehmen wie Ihrem haben wir besonders viel Erfahrung.“ Branche darf weit gefasst sein (z. B. „Dienstleister“), aber alles muss wahr sein."},
  {"p": "T", "y": "Präsentation", "t": "4:01", "x": "Statt „Uns ist immer besonders wichtig, dass wir erst mal die Situation analysieren“ → „Damit Sie das Ergebnis bekommen, das Sie haben wollen, analysieren wir erst mal …“. Statt „Wir haben viel Erfahrung mit der Anreise …“ → „Schauen Sie, die Anreise ist ja immer ein kritischer Punkt, und damit das bei Ihnen kein kritischer Punkt ist, machen wir für Sie erstens, zweitens, drittens.“"},
  {"p": "T", "y": "Gesprächseinstieg", "t": "6:00", "x": "Vorankündigung (Predeklaration) vor der Bedarfsanalyse: „Damit wir hier und heute nur über die Dinge sprechen, die auch für Sie interessant sind, habe ich zum Start ein paar kurze Fragen. Ist es okay, wenn wir die kurz durchgehen?“"}]},
"46-cOhwD3No": {"seg": "allgemein", "target": "Agenturen (Umsatzziele)", "watch": false, "why": "", "skip": "Eigenwerbung/Geschäftsmodell; Kernaussage (Vertrieb vor Positionierung, bewährte Zielgruppen wie Handwerk) schon in Nr. 25 erfasst","items":[
]},
"9fzGw_reDYs": {"seg": "allgemein", "target": "Coaching-Call (Mindset im Vertrieb)", "watch": false, "why": "","items":[
  {"p": "K", "y": "Organisation", "t": "4:01", "x": "Läuft es gut (z. B. zwei Termine aus den ersten zwei Calls), nicht Feierabend machen, sondern weitertelefonieren – gute Tage müssen schlechte ausgleichen. „Wenn es zu leicht läuft: Gang hoch.“"}]},
"4yXqZaCVaXc": {"seg": "Privat", "target": "Anlagen-/Haustechnik-Anbieter → Hausbesitzer (Coaching-Call, Julian formuliert)", "watch": false, "why": "","items":[
  {"p": "T", "y": "Preis", "t": "0:00", "x": "Bei „zu teuer“ selbstbewusst bleiben und nicht sofort mit dem Maximalrabatt „in die Knie gehen“ – jeder Rabatt geht von der Marge ab."},
  {"p": "T", "y": "Einwand", "e": "Zu teuer / kriege ich woanders günstiger", "t": "1:01", "x": "Alternative statt Rabatt: „Was ich Ihnen gerade angeboten habe, ist die optimale Variante für Ihr Haus … Wir haben jetzt eine Möglichkeit, dass wir Ihnen ein Alternativangebot rechnen. Es wird von der Rendite hinten raus nicht ganz so stark sein … da verbauen wir vielleicht andere Teile, die auf den ersten Blick günstiger sind, die aber früher getauscht werden müssen … Ich mache das sehr gerne. Oder wir gehen jetzt einmal mit der bestmöglichen Variante … Was denken Sie? Sollen wir noch mal ein anderes Angebot durchrechnen?“"},
  {"p": "T", "y": "Preis", "e": "Können Sie mir bei der Premium-Variante noch einen Rabatt geben?", "t": "3:01", "x": "„Vielleicht war das jetzt gerade mein Fehler … Ich muss Ihnen ehrlich sagen, ich habe Ihnen jetzt schon meinen bestmöglichen Preis kalkuliert. Ich weiß, andere schlagen erst mal künstlich was drauf, damit sie hinterher was abziehen können. Ist nicht so mein Ding. … Deshalb die Frage: Wie kommen wir da jetzt vielleicht trotzdem zusammen?“ – standhaft bleiben; viele fragen nur, um zu prüfen, ob noch was geht."}]},
"vlN2igIk_84": {"seg": "KMU", "target": "Unternehmenskauf/-nachfolge → Inhaber (Coaching-Call zu Zentrale und Vorzimmer)", "watch": true, "why": "Betonung bei der Sekretärin wird vorgemacht („ist dran“ schnell und hoch; Vorzimmer ruhig wie ein Arzt) – nur hörbar","items":[
  {"p": "K", "y": "Prinzip", "t": "0:00", "x": "Wichtigste Aufgabe in Zentrale und Vorzimmer: nicht nach Verkäufer klingen, sondern wie jemand, der normalerweise durchgestellt wird (Lieferant, Steuerberater, Kunde). Es geht um Status."},
  {"p": "K", "y": "Sekretärin", "t": "2:00", "x": "Negativbeispiel (Teilnehmer, Vorzimmer): „Frau Soundso, danke, dass wir kurz sprechen. Peter kennt mich gar nicht … es geht um ein ziemlich vertrauliches Thema …“ – entschuldigend und „kennt mich nicht“ = niedriger Status."},
  {"p": "K", "y": "Sekretärin", "t": "5:01", "x": "Zentrale: „Hallo, hier ist der Julian Mahnken, grüß Sie.“ (unverbindlich, ohne Firmennamen) → „Wenn Sie mich gleich einmal zum [Vorname Nachname] weiterstellen, dann richten Sie gerne aus, der [Vorname Nachname] ist dran.“ – „ist dran“ schnell und mit der Stimme hoch; meist kommt danach schon das Durchstellen. Optional: „Ich warte eben, danke.“"},
  {"p": "K", "y": "Sekretärin", "t": "8:01", "x": "Persönliches Vorzimmer: nicht fordernd wie in der Zentrale (das lässt sie sich nicht gefallen), sondern ruhig, straight, leicht gelangweilt – „so spricht ein Arzt oder Rechtsanwalt“ (hoher Status, null aufgeregt). Wörtliche Vorzimmer-Formulierung im Ausschnitt nicht enthalten."}]}
};
